@page "/dashboard"
@using sv_012228fd9bb54606986b9d448ca6319b.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @if (_alertCount > 0)
            {
                <span class="text-danger">@_alertCount</span>
            }
            else
            {
                <span class="text-success">0</span>
            }
        </p>
        <p class="card-text text-muted">
            Items below minimum stock level. Refreshes every 10 seconds.
        </p>
    </div>
</div>

@code {
    private int _alertCount;
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes (timer fires from background thread).
        _alertHandler = () => InvokeAsync(() =>
        {
            _alertCount = AlertService.CurrentAlertCount;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        // Subscribe to warehouse changes so the heading updates immediately.
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling — ref-counted, so the sidebar badge benefits too.
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.StopPolling();
    }
}

